import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: Test fixtures
const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99, quantity: 2 }],
  total: 59.98,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

const renderCheckout = () => {
  return render(
    <CartProvider value={mockCart}>
      <PaymentProvider value={mockPayment}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Happy Path - Complete Flow', () => {
    it('completes checkout through all steps', async () => {
      const user = userEvent.setup();
      renderCheckout();

      // Shipping step
      await user.type(screen.getByRole('textbox', { name: /street/i }), '123 Main St');
      await user.type(screen.getByRole('textbox', { name: /city/i }), 'Springfield');
      await user.type(screen.getByRole('textbox', { name: /state/i }), 'IL');
      await user.type(screen.getByRole('textbox', { name: /zip/i }), '62701');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111');
      await user.type(screen.getByRole('textbox', { name: /expiry/i }), '12/25');
      await user.type(screen.getByRole('textbox', { name: /cvv/i }), '123');
      await user.type(screen.getByRole('textbox', { name: /name on card/i }), 'Jean-Luc Picard');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review and submit
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('heading', { name: /order confirmed/i })).toBeInTheDocument();
      });
    });
  });

  describe('Form Validation', () => {
    it('displays error for invalid ZIP code format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByRole('textbox', { name: /zip/i }), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code required/i);
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = renderCheckout();
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });

  describe('Edge Cases', () => {
    it('displays empty cart message when no items', () => {
      render(<Checkout />, { cart: { items: [], total: 0 } });
      expect(screen.getByText(/your cart is empty/i)).toBeInTheDocument();
    });
  });
});
```

